pat=re.compile(r'^window\.G = .*;\s*$',re.M)
for t in TOPICS:
  n=t['n'];fin=dict(t['finale']);fin.setdefault('mood',f'Як вам {n}-та сторінка?');fin.setdefault('moodSay','Дякую! Гортаймо щоденник далі!')
  G={"id":f"3-T{n}","year":"index.html","cls":f"3 клас · Т{n}","title":t['title'],"idleHint":20000,"intro":t['intro'],"learn":t['learn'],
     "mapSay":"Ось сторінка мого щоденника. Відкривайте завдання по черзі. Хочете змагатися — увімкніть «Команди».","mapDone":"Усі завдання виконано! Натисніть на щоденник, щоб заповнити сторінку.",
     "finIcon":"📔","finName":f"Сторінка {n}","stages":t['stages'],"finale":fin,"T":T}
  for s in G['stages']:
    if s['type']=='pixel':
      for L in s['levels']:assert all(len(r)==len(L['rows'][0]) for r in L['rows']),n
    if s['type']=='bug':
      for R in s['rounds']:assert 0<=R['bad']<len(R['steps']),n
  hh=pat.sub(lambda m:'window.G = '+json.dumps(G,ensure_ascii=False)+';',tpl,count=1)
  hh=re.sub(r'<title>[^<]*</title>',f'<title>3 клас · Т{n} · {t["title"]}</title>',hh,count=1)
  open(D+f't{n}.html','w',encoding='utf8').write(hh)
ix=open(D+'index.html',encoding='utf8').read()
L=re.search(r'const LESSONS=\{[^}]*\}',ix).group(0);Ld=json.loads(L[len('const LESSONS='):])
Sd=json.loads(re.search(r'const STAGES=(\{[^}]*\})',ix).group(1))
for t in TOPICS: Ld[str(t['n'])]=f"t{t['n']}.html";Sd[str(t['n'])]=len(t['stages'])
ix=ix.replace(L,'const LESSONS='+json.dumps(Ld,ensure_ascii=False,separators=(',',':')))
ix=re.sub(r'const STAGES=\{[^}]*\}','const STAGES='+json.dumps(Sd,separators=(',',':')),ix,count=1)
open(D+'index.html','w',encoding='utf8').write(ix)
print('ok',[t['n'] for t in TOPICS])
